151	// claudeDirectlyImportsAgents recognizes a standalone @path directive outside the Markdown
152	// regions where Claude suppresses imports. Ambiguous syntax returns false so the direct pointer
153	// remains in place.
154	func claudeDirectlyImportsAgents(claudePath, agentsPath string) (bool, error) {
155		content, err := os.ReadFile(claudePath)
156		if err != nil {
157			if os.IsNotExist(err) {
158				return false, nil
159			}
160			return false, err
161		}
162		var found, fence bool
163		var until string
164		var fenceChar byte
165		var fenceWidth int
166		var codeTicks int
167		for _, raw := range strings.Split(string(content), "\n") {
168			indent := markdownIndent(raw)
169			line := strings.TrimSpace(raw)
170			if until != "" {
171				if strings.Contains(line, until) {
172					until = ""
173				}
174				continue
175			}
176			if strings.Contains(line, agentPointerBegin) {
177				if !strings.Contains(line, agentPointerEnd) {
178					until = agentPointerEnd
179				}
180				continue
181			}
182			if strings.Contains(line, agentPointerEnd) {
183				return false, nil
184			}
185			if strings.Contains(line, "<!--") {
186				if !strings.Contains(line, "-->") {
187					until = "-->"
188				}
189				continue
190			}
191			if strings.Contains(line, "-->") {
192				return false, nil
193			}
194			if fence {
195				width := len(line) - len(strings.TrimLeft(line, string(fenceChar)))
196				if indent <= 3 && width >= fenceWidth && strings.TrimSpace(line[width:]) == "" {
197					fence = false
198				}
199				continue
200			}
201			if indent <= 3 && len(line) >= 3 && (strings.HasPrefix(line, "```") || strings.HasPrefix(line, "~~~")) {
202				fence, fenceChar = true, line[0]
203				fenceWidth = len(line) - len(strings.TrimLeft(line, string(fenceChar)))
204				continue
205			}
206			if codeTicks != 0 || strings.Contains(line, "`") {
207				codeTicks = nextCodeSpanWidth(line, codeTicks)
208				continue
209			}
210			// Preserve raw indentation: trimming must not turn an indented Markdown code
211			// example into a live import and suppress Claude's direct guide pointer.
212			if indent >= 4 {
213				continue
214			}
215			if !strings.HasPrefix(line, "@") {
216				continue
217			}
218			imported := strings.TrimPrefix(line, "@")
219			if imported == "" || len(strings.Fields(imported)) != 1 {
220				continue
221			}
222			candidate := imported
223			if !filepath.IsAbs(candidate) {
224				candidate = filepath.Join(filepath.Dir(claudePath), candidate)
225			}
226			if filepath.Clean(candidate) == filepath.Clean(agentsPath) {
227				found = true
228			}
229		}
230		return found && until == "" && !fence, nil
231	}
