233	func markdownIndent(line string) int {
234		indent := 0
235		for i := 0; i < len(line); i++ {
236			switch line[i] {
237			case ' ':
238				indent++
239			case '\t':
240				return 4
241			default:
242				return indent
243			}
244		}
245		return indent
246	}
247	
248	func nextCodeSpanWidth(line string, open int) int {
249		for cursor := 0; cursor < len(line); {
250			if line[cursor] != '`' {
251				cursor++
252				continue
253			}
254			width := len(line[cursor:]) - len(strings.TrimLeft(line[cursor:], "`"))
255			if open == 0 {
256				open = width
257			} else if open == width {
258				open = 0
259			}
260			cursor += width
261		}
262		return open
263	}
