265	// upsertPointerBlock appends the block to path (creating the file if absent), or replaces the
266	// existing marker-delimited block in place, so repeated runs never duplicate content.
267	func upsertPointerBlock(path, block string) error {
268		existing, err := os.ReadFile(path)
269		if err != nil && !os.IsNotExist(err) {
270			return err
271		}
272		content := string(existing)
273		begin := strings.Index(content, agentPointerBegin)
274		end := strings.Index(content, agentPointerEnd)
275		switch {
276		case begin >= 0 && end > begin:
277			content = content[:begin] + strings.TrimSuffix(block, "\n") + content[end+len(agentPointerEnd):]
278		case len(content) == 0:
279			content = block
280		default:
281			if !strings.HasSuffix(content, "\n") {
282				content += "\n"
283			}
284			content += "\n" + block
285		}
286		return os.WriteFile(path, []byte(content), 0o644)
287	}
