23	func TestAgentGuidePrintsDoctrine(t *testing.T) {
24		var out bytes.Buffer
25		if err := Run(context.Background(), Options{Stdout: &out, Stderr: &out}, []string{"agent-guide"}); err != nil {
26			t.Fatal(err)
27		}
28		for _, want := range []string{
29			"SEARCH FIRST",
30			"entire graph search",
31			"--profile full",
32			"VERIFY before stopping",
33			"never trade resolution for fewer turns",
34		} {
35			if !strings.Contains(out.String(), want) {
36				t.Fatalf("agent-guide output missing %q:\n%s", want, out.String())
37			}
38		}
39		for _, withdrawn := range []string{"54.9%", "57.7%", "roughly in half", "make the minimal edit, and STOP"} {
40			if strings.Contains(out.String(), withdrawn) {
41				t.Fatalf("agent-guide output retained withdrawn guidance %q:\n%s", withdrawn, out.String())
42			}
43		}
44	}
