46	func TestInitAgentsInstallsAndIsIdempotent(t *testing.T) {
47		repo := t.TempDir()
48		// pre-existing AGENTS.md must be preserved, not clobbered
49		if err := os.WriteFile(filepath.Join(repo, "AGENTS.md"), []byte("# my project rules\n"), 0o644); err != nil {
50			t.Fatal(err)
51		}
52	
53		var out bytes.Buffer
54		run := func() {
55			t.Helper()
56			if err := Run(context.Background(), Options{Stdout: &out, Stderr: &out}, []string{"init-agents", "--repo", repo}); err != nil {
57				t.Fatal(err)
58			}
59		}
60		run()
61	
62		guide, err := os.ReadFile(filepath.Join(repo, ".entire", "graph-agent.md"))
63		if err != nil {
64			t.Fatalf("guide not written: %v", err)
65		}
66		if !strings.Contains(string(guide), "SEARCH FIRST") {
67			t.Fatalf("guide content wrong:\n%s", guide)
68		}
69	
70		agents, err := os.ReadFile(filepath.Join(repo, "AGENTS.md"))
71		if err != nil {
72			t.Fatal(err)
73		}
74		if !strings.Contains(string(agents), "# my project rules") {
75			t.Fatalf("existing AGENTS.md content clobbered:\n%s", agents)
76		}
77		if !strings.Contains(string(agents), agentPointerBegin) || !strings.Contains(string(agents), ".entire/graph-agent.md") {
78			t.Fatalf("pointer block missing from AGENTS.md:\n%s", agents)
79		}
80		if !strings.Contains(string(agents), "resolution-first guidance") ||
81			strings.Contains(string(agents), "roughly in half") {
82			t.Fatalf("pointer block retained withdrawn doctrine:\n%s", agents)
83		}
84	
85		claude, err := os.ReadFile(filepath.Join(repo, "CLAUDE.md"))
86		if err != nil {
87			t.Fatalf("CLAUDE.md not created: %v", err)
88		}
89		if !strings.Contains(string(claude), "@.entire/graph-agent.md") {
90			t.Fatalf("CLAUDE.md missing import line:\n%s", claude)
91		}
92	
93		// Idempotence includes the complete bytes, not only the marker count.
94		run()
95		agents2, _ := os.ReadFile(filepath.Join(repo, "AGENTS.md"))
96		if !bytes.Equal(agents, agents2) {
97			t.Fatalf("AGENTS.md changed on idempotent rerun:\nbefore:\n%s\nafter:\n%s", agents, agents2)
98		}
99		if got := strings.Count(string(agents2), agentPointerBegin); got != 1 {
100			t.Fatalf("pointer block duplicated (%d occurrences):\n%s", got, agents2)
101		}
102		claude2, _ := os.ReadFile(filepath.Join(repo, "CLAUDE.md"))
103		if !bytes.Equal(claude, claude2) {
104			t.Fatalf("CLAUDE.md changed on idempotent rerun:\nbefore:\n%s\nafter:\n%s", claude, claude2)
105		}
106		if got := strings.Count(string(claude2), agentPointerBegin); got != 1 {
107			t.Fatalf("CLAUDE.md block duplicated (%d occurrences):\n%s", got, claude2)
108		}
109	}
