111	func TestInitAgentsMigratesClaudeToAgentsInheritance(t *testing.T) {
112		repo := t.TempDir()
113		claudePath := filepath.Join(repo, "CLAUDE.md")
114		legacy := "# Claude-only rules\n\n@AGENTS.md\n\n" + testAgentPointerBlock + "\nKeep this footer.\n"
115		if err := os.WriteFile(claudePath, []byte(legacy), 0o644); err != nil {
116			t.Fatal(err)
117		}
118	
119		runInitAgentsForTest(t, repo)
120		claude := readFileForTest(t, claudePath)
121		if !strings.Contains(claude, "# Claude-only rules\n") || !strings.Contains(claude, "\nKeep this footer.\n") {
122			t.Fatalf("unmanaged CLAUDE.md content was not preserved:\n%s", claude)
123		}
124		if !strings.Contains(claude, "@AGENTS.md") {
125			t.Fatalf("user-owned AGENTS.md import was removed:\n%s", claude)
126		}
127		if !strings.Contains(claude, testInheritedAgentPointerBlock) {
128			t.Fatalf("legacy direct block was not migrated to inheritance notice:\n%s", claude)
129		}
130		if strings.Contains(claude, "@.entire/graph-agent.md") {
131			t.Fatalf("CLAUDE.md retained a duplicate direct guide import:\n%s", claude)
132		}
133		agents := readFileForTest(t, filepath.Join(repo, "AGENTS.md"))
134		if !strings.Contains(agents, testAgentPointerBlock) {
135			t.Fatalf("AGENTS.md lost the canonical direct guide pointer:\n%s", agents)
136		}
137	
138		runInitAgentsForTest(t, repo)
139		if rerun := readFileForTest(t, claudePath); rerun != claude {
140			t.Fatalf("migrated CLAUDE.md changed on rerun:\nbefore:\n%s\nafter:\n%s", claude, rerun)
141		}
