205	func TestInitAgentsIgnoresNonLiveAndExcludedAgentsMentions(t *testing.T) {
206		tests := []struct {
207			name    string
208			content string
209		}{
210			{name: "inline code", content: "Use `@AGENTS.md` as an example.\n"},
211			{name: "backtick fence", content: "```md\n@AGENTS.md\n```\n"},
212			{name: "tilde fence", content: "~~~md\n@AGENTS.md\n~~~\n"},
213			{name: "html comment", content: "<!-- @AGENTS.md -->\n"},
214			{name: "managed region", content: agentPointerBegin + "\n@AGENTS.md\n" + agentPointerEnd + "\n"},
215			{name: "word prefix", content: "owner@AGENTS.md\n"},
216			{name: "filename suffix", content: "@AGENTS.md.backup\n"},
217			{name: "path suffix", content: "@AGENTS.md/example\n"},
218			{name: "space-indented code", content: "Example:\n\n    @AGENTS.md\n"},
219			{name: "tab-indented code", content: "Example:\n\n\t@AGENTS.md\n"},
220			{name: "short fence cannot close", content: "````md\nexample\n```\n@AGENTS.md\n"},
221			{name: "annotated fence cannot close", content: "```md\nexample\n```not-a-close\n@AGENTS.md\n"},
222			{name: "unclosed code span hides later import", content: "`unfinished example\n@AGENTS.md\n"},
223			{name: "unclosed fence is ambiguous", content: "@AGENTS.md\n```md\nunfinished\n"},
224			{name: "unclosed comment is ambiguous", content: "@AGENTS.md\n<!-- unfinished\n"},
225		}
226		for _, tt := range tests {
227			t.Run(tt.name, func(t *testing.T) {
228				repo := t.TempDir()
229				if err := os.WriteFile(filepath.Join(repo, "CLAUDE.md"), []byte(tt.content), 0o644); err != nil {
